require "test_helper"

# Generated by maquina:oauth.
class OauthAuthorizationCodeTest < ActiveSupport::TestCase
  setup do
    @client = oauth_clients(:inspector)
    @verifier, @challenge = pkce_pair
    @raw = OauthAuthorizationCode.issue!(user: users(:mcp_member), client: @client, redirect_uri: INSPECTOR_REDIRECT_URI,
      code_challenge: @challenge, scope: "read", resource: MCP_RESOURCE)
  end

  test "stores only the digest of the code" do
    code = OauthAuthorizationCode.find_by!(code_digest: AccessToken.digest(@raw))

    assert_not_includes code.attributes.values, @raw
  end

  test "redeems once" do
    code = redeem

    assert_equal users(:mcp_member), code.user
    assert code.reload.used_at
    assert_raises(OauthAuthorizationCode::InvalidGrant) { redeem }
  end

  test "expires after ten minutes" do
    travel OauthAuthorizationCode::TTL + 1.second

    assert_raises(OauthAuthorizationCode::InvalidGrant) { redeem }
  end

  test "still works just inside ten minutes" do
    travel OauthAuthorizationCode::TTL - 1.minute

    assert redeem
  end

  test "needs the verifier behind the challenge" do
    assert_raises(OauthAuthorizationCode::InvalidGrant) { redeem(verifier: pkce_pair.first) }
    # A plain challenge sent as the verifier is not S256.
    assert_raises(OauthAuthorizationCode::InvalidGrant) { redeem(verifier: @challenge) }
  end

  test "needs the same client and the exact redirect_uri" do
    other = OauthClient.create!(client_id: "https://other.example.com/client.json", client_name: "Other",
      redirect_uris: [INSPECTOR_REDIRECT_URI], metadata_fetched_at: Time.current)

    assert_raises(OauthAuthorizationCode::InvalidGrant) { redeem(client: other) }
    assert_raises(OauthAuthorizationCode::InvalidGrant) { redeem(redirect_uri: "#{INSPECTOR_REDIRECT_URI}/") }
    assert redeem
  end

  private

  def redeem(client: @client, redirect_uri: INSPECTOR_REDIRECT_URI, verifier: @verifier)
    OauthAuthorizationCode.redeem!(@raw, client: client, redirect_uri: redirect_uri, verifier: verifier)
  end
end
